Suppose that the assumptions of Theorem 2 hold, and fix a constant $\sigma > \sigma_{\mathrm{bd}}(a, b, m, \Delta)$. Then we have
	\begin{equation*}
		\limsup_{n \to \infty} \sup_{t \in [a + \sigma, b]} v_n(\omega, t, (m + 1)\Delta + 1)e^{\mu\left[t - (a + \sigma)\right]} \leq u(a + \sigma) \quad \text{for all} \quad \omega \in \Omega_T.
	\end{equation*}

Suppose that there exists $\gamma_0 \in (0, 1/ 2)$ such that
	\begin{equation}

		\lim_{n \to \infty} \alpha_n = 1 \quad \text{and} \quad \liminf_{n \to \infty} n^{\gamma_0}(1 - \alpha_n) > 0.
	\end{equation}
	If the offered load is $(m, \Delta)$-bounded on an interval $[a, b]$ and $\sigma(a, b, m, \Delta) < \sigma < b - a$, then there exist $c > 0$ and a set of probability one where the following statements hold:
	\begin{subequations}
		\begin{align}
			&\lim_{n \to \infty} \sup_{t \in [a + \sigma, b]} |\ell_n(t) - m \Delta| = 0,  \\
			&\lim_{n \to \infty} \sup_{t \in [a + \sigma, b]} n^\gamma\left|1 - q_n(t, i)\right| = 0 \quad \text{for all} \quad i \leq m \Delta \quad \text{and all} \quad \gamma \in [0, 1/2),  \\
			&\limsup_{n \to \infty} \sup_{t \in [a + \sigma, b]} \sum_{i > (m + 1)\Delta} q_n(t, i)\mathrm{e}^{\mu\left[t - (a + \sigma)\right]} \leq c. 
		\end{align} 
	\end{subequations}
	The constant $c$ can be taken equal to $u(a + \sigma)$.

Suppose that there exists $\gamma_0 \in (0, 1/ 2)$ such that
	\begin{equation}

		\lim_{n \to \infty} \alpha_n = 1 \quad \text{and} \quad \liminf_{n \to \infty} n^{\gamma_0}(1 - \alpha_n) > 0.
	\end{equation}
	If the offered load is $(m, \Delta)$-bounded on an interval $[a, b]$ and $\sigma(a, b, m, \Delta) < \sigma < b - a$, then there exist $c > 0$ and a set of probability one where the following statements hold:
	\begin{subequations}
		\begin{align}
			&\lim_{n \to \infty} \sup_{t \in [a + \sigma, b]} |\ell_n(t) - m \Delta| = 0,  \\
			&\lim_{n \to \infty} \sup_{t \in [a + \sigma, b]} n^\gamma\left|1 - q_n(t, i)\right| = 0 \quad \text{for all} \quad i \leq m \Delta \quad \text{and all} \quad \gamma \in [0, 1/2),  \\
			&\limsup_{n \to \infty} \sup_{t \in [a + \sigma, b]} \sum_{i > (m + 1)\Delta} q_n(t, i)\mathrm{e}^{\mu\left[t - (a + \sigma)\right]} \leq c. 
		\end{align} 
	\end{subequations}
	The constant $c$ can be taken equal to $u(a + \sigma)$.

Suppose the hypotheses of Theorem 2 hold, and fix a constant
	\begin{align*}
		\sigma > \sigma_{\mathrm{bd}}(a, b, m, \Delta) \vcentcolon= \begin{cases}
			\frac{1}{\mu}\left[\log\left(\frac{u(a) - \rho_{\max}}{(m + 1) \Delta - \rho_{\max}}\right)\right]^+	&	\text{if} \quad u(a) > \rho_{\max}, \\
			0	&	\text{if} \quad u(a) \leq \rho_{\max},
		\end{cases}
	\end{align*}
	with $\rho_{\max}$ as in Definition def: (Delta, m)-bounded. For each $\omega \in \Omega_T$, there exists $n_{\mathrm{bd}}(\omega)$ such that
	\begin{align*}
		\ell_n(\omega, t) \leq m \Delta \quad \text{for all} \quad t \in [a + \sigma, b] \quad \text{and all} \quad n \geq n_{\mathrm{bd}}(\omega).
	\end{align*}

\begin{align}
			&\lim_{n \to \infty} \sup_{t \in [a + \sigma, b]} |\ell_n(t) - m \Delta| = 0,  \\
			&\lim_{n \to \infty} \sup_{t \in [a + \sigma, b]} n^\gamma\left|1 - q_n(t, i)\right| = 0 \quad \text{for all} \quad i \leq m \Delta \quad \text{and all} \quad \gamma \in [0, 1/2),  \\
			&\limsup_{n \to \infty} \sup_{t \in [a + \sigma, b]} \sum_{i > (m + 1)\Delta} q_n(t, i)\mathrm{e}^{\mu\left[t - (a + \sigma)\right]} \leq c. 
		\end{align}

Fix $\omega \in \Omega_T$ and $j \in \left\{i\Delta : i \geq 1\right\}$. Suppose that there exist an increasing sequence $\mathcal{K}$ of natural numbers and two sequences of random times $0 \leq \tau_{k, 1} \leq \tau_{k, 2} \leq T$ such that
	\begin{equation*}
		\ell_k(\omega, t) \leq j \quad \text{and} \quad q_k(\omega, t, j) < 1 \quad \text{for all} \quad t \in \left[\tau_{k, 1}(\omega), \tau_{k, 2}(\omega)\right) \quad \text{and} \quad k \in \mathcal{K}.
	\end{equation*}
	Then the next inequality holds for all $t \in \left[\tau_{k, 1}(\omega), \tau_{k, 2}(\omega)\right]$ and all $k \in \mathcal{K}$:
	\begin{equation*}
		\sum_{i = 1}^j q_k(\omega, t, i) - \sum_{i = 1}^j q_k\left(\omega, \tau_{k, 1}(\omega), i\right) \geq \int_{\tau_{k, 1}(\omega)}^t \left[\lambda(s) - \mu j\right]ds - 2\sup_{s \in [0, T]} \left|\delta_k(\omega, s, j)\right|.
	\end{equation*}

Suppose that the hypotheses of Theorem 2 hold. Fix $\omega \in \Omega_T$ and $j \in \left\{i\Delta : 0 \leq i \leq m\right\}$. Also, assume that there exist an increasing sequence $\mathcal{K} \subset \mathbbm{N}$, a constant $\varepsilon > 0$ and two sequences of random times $a + \varepsilon \leq \zeta_{k, 1} \leq \zeta_{k, 2} \leq b$ such that
	\begin{equation*}
		q_k\left(\omega, \zeta_{k, 1}(\omega), j\right) = 1 \quad \text{and} \quad \ell_k(\omega, t) \leq j \quad \text{for all} \quad t \in \left[\zeta_{k, 1}(\omega), \zeta_{k, 2}(\omega)\right] \quad \text{and} \quad k \in \mathcal{K}.
	\end{equation*}
	For all sufficiently large $k \in \mathcal{K}$ and all $\gamma \in [0, 1/2)$, we have
	\begin{equation*}
		\ell_k(\omega, t) = j \quad \text{and} \quad q_k(\omega, t, j) \geq 1 - k^{-\gamma} \quad \text{for all} \quad t \in \left[\zeta_{k, 1}(\omega), \zeta_{k, 2} (\omega)\right].
	\end{equation*}

Suppose that the following two conditions hold for a given $\omega \in \Omega_T$ and a given increasing sequence $\mathcal{K}$ of natural numbers.
	\begin{enumerate}
		\item[(a)] The sequence $\left\{q_k(\omega) : k \in \mathcal{K}\right\}$ converges to a function $q \in D_{\mathbbm{R}^{\mathbbm{N}}}[0, T]$ in the metric $\varrho$.

		\item[(b)] There exist $j \in \left\{i\Delta : i \geq 1\right\}$ and $0 \leq t_0 < t_1 \leq T$ such that
		\begin{equation*}
			\ell_k(\omega, t) \leq j \quad \text{and} \quad q_k(\omega, t, j) < 1 \quad \text{for all} \quad t \in [t_0, t_1] \quad \text{and all} \quad k \in \mathcal{K}.
		\end{equation*}
	\end{enumerate}
	Then the coordinate functions $q(i)$ are differentiable on $(t_0, t_1)$ for all $i > j$, and they satisfy
	\begin{equation*}
		\dot{q}(t, i) = -\mu i \left[q(t, i) - q(t, i + 1)\right] \quad \text{for all} \quad t \in (t_0, t_1) \quad \text{and all} \quad i > j.
	\end{equation*}
	Also, $\left\{v_k(\omega, j + 1) : k \in \mathcal{K}\right\}$ converges uniformly over $[0, T]$ to a function $v(j + 1)$ such that
	\begin{equation*}
		v(t, j + 1) < u(t_0)\mathrm{e}^{-\mu (t - t_0)} \quad \text{for all} \quad t \in [t_0, t_1].
	\end{equation*}

For each $\omega \in \Omega_T$, the sequence $\left\{u_n(\omega) : n \geq 1\right\}$ converges uniformly over $[0, T]$ to the function $u : [0, T] \longrightarrow [0, \infty)$ defined in (4) by
	\begin{equation*}
		u(0) \vcentcolon= \sum_{i = 1}^\infty q(0, i) \quad \text{and} \quad u(t) \vcentcolon= u(0)\mathrm{e}^{-\mu t} + \int_0^t \rho(s) \mu \mathrm{e}^{-\mu(t - s)}ds \quad \text{for all} \quad t \in [0, T].
	\end{equation*}

There exist a positive constant $B_T \in \mathbbm{N}$ and a set of probability one $\Omega_T \subset \Gamma_T$ such that the following two properties hold.
	\begin{enumerate}
		\item[(a)] For each $\omega \in \Omega_T$, there exists $n_T(\omega)$ such that
		\begin{equation}

			q_n(\omega, t, B_T + 1) = 0 \quad \text{and} \quad \ell_n(\omega, t) \leq B_T \quad \text{for all} \quad t \in [0, T] \quad \text{and all} \quad n \geq n_T(\omega).
		\end{equation}

		\item[(b)] The next limits hold on $\Omega_T$ for all $\gamma \in [0, 1/2)$.
	\end{enumerate}
	\begin{subequations}
		\begin{align}
			&\lim_{n \to \infty} q_n(0) = q(0),  \\
			&\lim_{n \to \infty} \sup_{t \in [0, T]} n^\gamma\left|\frac{1}{n} \mathcal{N}_n^\lambda(t) - \int_0^t \lambda(s)ds\right| = 0,  \\
			&\lim_{n \to \infty} \sup_{t \in [0, \mu iT]} n^\gamma\left|\frac{1}{n} \mathcal{N}_i(nt) - t\right| = 0 \quad \text{for all} \quad i \geq 1. 
		\end{align}
	\end{subequations}
